const circularShift = (x, shift) => {
  const s = x.toString();
  const n = s.length;
  if (shift > n) {
    return s.split('').reverse().join('');
  }
  const offset = shift % n;
  if (offset === 0) return s;
  const rightPart = s.slice(n - offset);
  const leftPart = s.slice(0, n - offset);
  return rightPart + leftPart;
};

