const pluck = (arr) => {
  if (!arr || arr.length === 0) {
    return [];
  }

  let smallestEven = Infinity;
  let smallestIndex = -1;

  for (let i = 0; i < arr.length; i++) {
    const val = arr[i];
    if (val % 2 === 0) {
      if (val < smallestEven) {
        smallestEven = val;
        smallestIndex = i;
      }
    }
  }

  if (smallestIndex === -1) {
    return [];
  }

  return [smallestEven, smallestIndex];
};

